      "title": "고유링크)실링팬 관련 설문조사-최근 3년이내 실링팬 설치 경험자(150명) 30~59세 기혼여성",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/131013",
      "target_age": "",
