      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n11/27~12/3 ) 20대 남성) ㅇ배 흡연 설문&좌담회_2차 방문 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.11. 10:07\n조회 21\n구독\n11/27~12/3 ) 20,30대 남성) ㅇ배 흡연 설문&좌담회_2차 방문 조사\n신청하신분은 재신청 안하셔도 됩니다\n조사방법/\n1. 1차 사무실 내방해서 간단한 조사 방법을 듣고, 담배를 가져 가서 3일동안 흡연을 해야함. 1갑 담배 흡연할때마다 링크에 들어가서 설문조사 진행함.\n2. 시제품이기때문에 제공받은 담배는 흡연후 버리지 말고 봉투에 넣어서 잘 챙겨놓아야 함\n3. 2차 방문은 좌담회로 진행하고, 올때에는 흡연한 제품을 다 가지고 와야 함.\n응답자조건 :\n그룹1 : 연초 주 흡연자, 전자 담배 혼용X / 에쎄 히말라야, 히말라야 윈터, 히말라야 샤인 주 흡연하는 20,30대 남성\n그룹2 : 연초 주 흡연자, 전자 담배 혼욘X / 말보로 비스타 포레스트 미스트, 말보로 비스타 가든 스플래쉬, 말보로 비스타 블로썸 미스트, 던힐 파인컷 멜로우 크러쉬 주 흡연하는 20,30대 남성\n그룹3 : 연초 주 흡연자, 전자 담배 혼용O / 그룹1.2 담배 브랜드 중 주 흡연하는 담배를 흡연하면서 전자담배를 혼용하는 20,30대 남성\n1차 방문 : 11월 27일 / 2차 방문 : 12월 3일\n그룹1 : 1차 방문 11월 27일(금) 4시 (소요 시간 30분) , 2차 방문 12월 3일(목) 4시 (소요 시간 1시간) / 참석 사례비 : 8만원 (2차 조사 참석 시 일괄 지급)\n그룹2 : 1차 방문 11월 27일(금) 7시30분 (소요 시간 30분) . 2차 방문 12월 3일(목) 7시30분 (소요 시간 1시간) / 참석 사례비 : 8만원 (2차 조사 참석 시 일괄 지급)\n그룹3 : 1차 방문 11월 27일(금) 6시 (소요 시간 30분) . 2차 방문 12월 3일(목) 6시 (소요 시간 1시간) / 참석 사례비 : 8만원 (2차 조사 참석 시 일괄 지급)\n장 소 : 1차 방문 ( 2호선, 9호선 당산역 부근) / 2차 방문 (9호선 언주역 부근)\nhttps://forms.gle/u2BmmiTYg7yr9JoM6\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.11. 16:22 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/27~12/3 ) 30대 남성) ㅇ배 흡연 설문&좌담회_2차 방문 조사\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n11/27~12/3 ) 20대 남성) ㅇ배 흡연 설문&좌담회_2차 방문 조사\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n성남시 아동친화도시 표준조사 온라인 설문조사 -경기도 성남시 수정구, 분당구에 소재한 초등학교/중학교 학부모\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n급급급) 30~39세 여성) 200만원 상당 리프팅 시술 체험 및 SNS 릴스 촬영 참여자 모집 [사례비: 30만원]\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
