      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/23(월) ~ 12/2(수) 만 18세 이상 성인남성) 라이브 방송 시청 및 유료 후원 이용자 대상 온라인 줌 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.11. 12:09\n조회 96\n구독\n11/23(월) ~ 12/2(수) 만 18세 이상 성인남,여) 라이브 방송 시청 및 유료 후원 이용자 대상 온라인 줌 인터뷰\n1. 조사대상\n- 만 18세 이상 남, 여\n- 평소 유튜브, 틱톡, SOOP, 치지직 등에서 라이브 방송을 정기적으로 시청하는 사람\n- 라이브 방송 중 크리에이터에게 유료 선물, 슈퍼챗, 별풍선, 치즈 등의 방식으로 후원한 사람\n- 최근 3개월 이내 라이브 방송에서 유료 후원을 한 사람\n- 평소 즐겨 시청하는 라이브 방송이나 크리에이터가 있는 사람\n- 라이브 방송에서 PK 배틀, 라이브 매치 등 크리에이터 간 경쟁 방송을 시청한 사람 우대\n2. 조사방법과 사례\n- 방법 : Zoom을 활용한 온라인 화상 인터뷰\n- 일시 : 11/23(월) ~ 12/2(수) 중 / 시간은 추후 안내드립니다\n- 사례 : 현금 8만원 계좌 입금\n3. 조사 참여신청\n- 신청양식\n이름/나이/성별/직업/거주지/평소 이용하는 라이브 방송 플랫폼/주로 시청하는 라이브 방송 또는 크리에이터/주로 시청하는 방송 분야/최근 라이브 방송 유료 후원 경험/후원한 플랫폼 및 시기\n-신청 예시\n홍길동/28세/남자/회사원/서울시 종로구/유튜브, 틱톡, SOOP, 치지직/침착맨, 랄로/소통, 게임방송/유료 후원 경험 O/유튜브 기프트(26년 10월), 치지직 치즈 후원(26년 11월)\n4. 대상 선정\n- 신청내용 확인 후 1. 문자로 대상 선정을 위한 온라인 링크 송부받아 링크에 응답, 2. 전화로 최종 확인\nhttps://forms.gle/rNnZbBiVyzMscDuj8\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.11. 16:20 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/23(월) ~ 12/2(수) 만 18세 이상 성인여성) 라이브 방송 시청 및 유료 후원 이용자 대상 온라인 줌 인터뷰\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n11/23(월) ~ 12/2(수) 만 18세 이상 성인남성) 라이브 방송 시청 및 유료 후원 이용자 대상 온라인 줌 인터뷰\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n12/1~3)집방문인터뷰 +7일온라인과제 (30만원) 자녀놀이와 장난감에 관한 인터뷰 ( 반드시 여아 만6세~만12세 따님과 함께 참석 신청( 아버님 )\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n12/1~3)집방문인터뷰 +7일온라인과제 (30만원) 자녀놀이와 장난감에 관한 인터뷰 ( 반드시 여아 만6세~만12세 따님과 함께 참석 신청( 엄마 )\n좌담회알바좌담회카페\n26.11.11.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
