      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —30대 남녀) 난임 환자 및 환자의 배우자\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.11. 16:55\n조회 27\n구독\n11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —30대 남녀) 난임 환자 및 환자의 배우자\n11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —20세 이상 남녀) 난임 환자 및 환자의 배우자\n조사 대상: 국내 거주 만 18세 이상 난임 치료 경험자 및 난임 환자의 배우자 총 6명\n난임 환자의 배우자의 경우 최대 2명 가능\nIVF(체외수정/시험관 시술)환자 최소 3명 + 비의학적 목적의 난자 동결 및 인공수정(IUI)·호르몬 치료 경험자도 포함해 고르게 모집\n인터뷰 방식 및 길이: 온라인 인터뷰 60분\n인터뷰 기간: 11/30~\n필수 조건:\n지난 1년 6개월 이내 본인 또는 배우자가 국내 사립병원에서 난임 치료를 받았거나 현재 받고 있는 분\n그 중 본인 부담·보험·지원금·저축·이미 받은 대출 등을 통해 치료비를 부담할 수 있는 분\nIVF 환자 최소 4명 (나머지는 난자 동결 및 인공 수정 환자를 포함해 고르게 리크루팅)\n배우자의 경우 병원 선택이나 치료 지속 여부 등 의사결정에 치료 당사자와 동등하거나 더 적극적으로 참여한 분\n병원 쿼터\n차병원·마리아병원·미라클 여성의원·리오라 여성의원 환자 합산 최소 3명 (동일 클리닉에서 최대 1명)\n개인 난임 의원 최대 3명 + 난임 클리닉 체인 & 난임/IVF센터 보유 사립 병원 이용자 고르게 모집\nIVF·IUI 치료 단계별 쿼터\n첫 시술 주기 진행 중 최소 1명+\n첫 시술 후 임신에 성공하지 못한 환자 최소 1명+\n2주기 이상 시술 후 임신에 성공하지 못한 환자 최소 1명+\n시술 후 현재 임신 중이거나 출산한 환자 최대 1명+\n치료 2회 이상 시도한 환자 최소 2명, 실제로 사립 난임 병원을 변경 또는 진지하게 변경을 고민한 환자 최소 1명+\n인터뷰에서 본인 또는 배우자의 치료 경험을 편안하게 이야기할 수 있으며, 인터뷰 내용의 기밀 유지에 동의하는 분\n인터뷰 대상자 : 10만원\nhttps://forms.gle/C3YRUsu3ukmvBkbH7\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —40대 남녀) 난임 환자 및 환자의 배우자\n좌담회알바좌담회카페\n26.11.11.\n댓글\n0\n11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —30대 남녀) 난임 환자 및 환자의 배우자\n좌담회알바좌담회카페\n26.11.11.\n댓글\n0\n11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —20대 남녀) 난임 환자 및 환자의 배우자\n좌담회알바좌담회카페\n26.11.11.\n댓글\n0\n11/25~26) 만 20~59세 여성) 아이스크림 좌담회\n좌담회알바좌담회카페\n26.11.11.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
