      "id": "69ca0ca71c991a438cd30629271fc6a9",
      "title": "11/30~) 온라인 인터뷰 60분 10만원 ) 체외수정/시험관 시술 조사 —20세 이상 여성) 난임 환자 및 환자의 배우자",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/131049",
      "target_age": "",
      "target_gender": "",
      "target_condition": "국내 거주 만 18세 이상 난임 치료 경험자 및 난임 환자의 배우자 총 6명",
      "date": "",
      "time": "",
      "duration": "",
      "reward": "",
